public class JacksonAnnotationIntrospector_refineDeserializationType_TriageGen1Test {

    private JacksonAnnotationIntrospector introspector;
    private MapperConfig<?> config;
    private TypeFactory typeFactory;
    private Annotated annotated;

    @Before
    public void setUp() {
        introspector = new JacksonAnnotationIntrospector();
        config = mock(MapperConfig.class);
        typeFactory = TypeFactory.defaultInstance();
        annotated = mock(Annotated.class);
        when(config.getTypeFactory()).thenReturn(typeFactory);
    }

    /**
     * Test case where no annotation is present. 
     * Should return the base type unchanged.
     */
    @Test
    public void testRefineNoAnnotation() throws JsonMappingException {
        JavaType baseType = typeFactory.constructType(String.class);

        // We need to mock _findAnnotation behavior. Since it's protected/private, 
        // we rely on the fact that if we don't provide an annotation, it returns null.
        // In a real Jackson environment, this is handled by the introspector scanning.
        // Here we simulate the absence of @JsonDeserialize.

        // Since we cannot easily mock the protected _findAnnotation call directly 
        // without a spy, we use a subclass or rely on the fact that the introspector 
        // will return null if the mocked 'annotated' has no @JsonDeserialize.

        JavaType result = introspector.refineDeserializationType(config, annotated, baseType);

        assertEquals(baseType, result);
    }

    /**
     * Test case where @JsonDeserialize(as = SpecificClass.class) is present.
     * Should refine the base type to the specific class.
     */
    @Test
    public void testRefineWithExplicitClass() throws JsonMappingException {
        // Mocking the annotation finding logic requires a Spy because _findAnnotation is protected
        JacksonAnnotationIntrospector spyIntrospector = spy(new JacksonAnnotationIntrospector());

        JsonDeserialize annotation = mock(JsonDeserialize.class);
        when(annotation.as()).thenReturn(Integer.class);
        doReturn(annotation).when(spyIntrospector)._findAnnotation(any(), eq(JsonDeserialize.class));

        // Base type is Object, but annotation says Integer
        JavaType baseType = typeFactory.constructType(Object.class);
        when(annotated.getName()).thenReturn("testField");

        JavaType result = spyIntrospector.refineDeserializationType(config, annotated, baseType);

        assertEquals(Integer.class, result.getRawClass());
    }

    /**
     * Test case for Map-like types with keyAs refinement.
     */
    @Test
    public void testRefineMapKeyType() throws JsonMappingException {
        JacksonAnnotationIntrospector spyIntrospector = spy(new JacksonAnnotationIntrospector());

        JsonDeserialize annotation = mock(JsonDeserialize.class);
        when(annotation.keyAs()).thenReturn(Long.class);
        doReturn(annotation).when(spyIntrospector)._findAnnotation(any(), eq(JsonDeserialize.class));

        // Base type is Map<String, String>
        JavaType baseType = typeFactory.constructMapType(Map.class, String.class, String.class);
        when(annotated.getName()).thenReturn("testMap");

        JavaType result = spyIntrospector.refineDeserializationType(config, annotated, baseType);

        // Result should be Map<Long, String>
        assertEquals(Long.class, result.getKeyType().getRawClass());
        assertEquals(String.class, result.getContentType().getRawClass());
    }

    /**
     * Test case for Collection/Array types with contentAs refinement.
     */
    @Test
    public void testRefineContentType() throws JsonMappingException {
        JacksonAnnotationIntrospector spyIntrospector = spy(new JacksonAnnotationIntrospector());

        JsonDeserialize annotation = mock(JsonDeserialize.class);
        when(annotation.contentAs()).thenReturn(Double.class);
        doReturn(annotation).when(spyIntrospector)._findAnnotation(any(), eq(JsonDeserialize.class));

        // Base type is List<String>
        JavaType baseType = typeFactory.constructCollectionType(java.util.List.class, String.class);
        when(annotated.getName()).thenReturn("testList");

        JavaType result = spyIntrospector.refineDeserializationType(config, annotated, baseType);

        // Result should be List<Double>
        assertEquals(Double.class, result.getContentType().getRawClass());
    }

    /**
     * Test case for combined refinement (Key and Content).
     */
    @Test
    public void testRefineMapKeyAndContent() throws JsonMappingException {
        JacksonAnnotationIntrospector spyIntrospector = spy(new JacksonAnnotationIntrospector());

        JsonDeserialize annotation = mock(JsonDeserialize.class);
        when(annotation.keyAs()).thenReturn(Integer.class);
        when(annotation.contentAs()).thenReturn(Boolean.class);
        doReturn(annotation).when(spyIntrospector)._findAnnotation(any(), eq(JsonDeserialize.class));

        JavaType baseType = typeFactory.constructMapType(Map.class, String.class, String.class);
        when(annotated.getName()).thenReturn("testMapFull");

        JavaType result = spyIntrospector.refineDeserializationType(config, annotated, baseType);

        assertEquals(Integer.class, result.getKeyType().getRawClass());
        assertEquals(Boolean.class, result.getContentType().getRawClass());
    }

    /**
     * Test failure case: IllegalArgumentException during specialized type construction for main type.
     */
    @Test(expected = JsonMappingException.class)
    public void testRefineMainTypeFailure() throws JsonMappingException {
        JacksonAnnotationIntrospector spyIntrospector = spy(new JacksonAnnotationIntrospector());

        JsonDeserialize annotation = mock(JsonDeserialize.class);
        // Using a class that will cause issues with constructSpecializedType if possible, 
        // but since we want to trigger the catch block, we mock the typeFactory to throw.
        when(annotation.as()).thenReturn(String.class);
        doReturn(annotation).when(spyIntrospector)._findAnnotation(any(), eq(JsonDeserialize.class));

        MapperConfig<?> mockConfig = mock(MapperConfig.class);
        TypeFactory mockTf = mock(TypeFactory.class);
        when(mockConfig.getTypeFactory()).thenReturn(mockTf);
        when(mockTf.constructSpecializedType(any(), any())).thenThrow(new IllegalArgumentException("Simulated Error"));

        JavaType baseType = typeFactory.constructType(Object.class);
        when(annotated.getName()).thenReturn("failField");

        spyIntrospector.refineDeserializationType(mockConfig, annotated, baseType);
    }

    /**
     * Test failure case: IllegalArgumentException during key type refinement.
     */
    @Test(expected = JsonMappingException.class)
    public void testRefineKeyTypeFailure() throws JsonMappingException {
        JacksonAnnotationIntrospector spyIntrospector = spy(new JacksonAnnotationIntrospector());

        JsonDeserialize annotation = mock(JsonDeserialize.class);
        when(annotation.keyAs()).thenReturn(String.class);
        doReturn(annotation).when(spyIntrosceptor)._findAnnotation(any(), eq(JsonDeserialize.class));

        // Mocking TypeFactory to throw on key type refinement
        MapperConfig<?> mockConfig = mock(MapperConfig.class);
        TypeFactory mockTf = mock(TypeFactory.class);
        when(mockConfig.getTypeFactory()).thenReturn(mockTf);
        // First call for main type (if applicable) and second for key type
        when(mockTf.constructSpecializedType(any(), any())).thenThrow(new IllegalArgumentException("Key Error"));

        JavaType baseType = typeFactory.constructMapType(Map.class, String.class, String.class);
        when(annotated.getName()).thenReturn("failKeyField");

        spyIntrospector.refineDeserializationType(mockConfig, annotated, baseType);
    }

    /**
     * Test failure case: IllegalArgumentException during content type refinement.
     */
    @Test(expected = JsonMappingException.class)
    public void testRefineContentTypeFailure() throws JsonMappingException {
        JacksonAnnotationIntrospector spyIntrospector = spy(new JacksonAnnotationIntrospector());

        JsonDeserialize annotation = mock(JsonDeserialize.class);
        when(annotation.contentAs()).thenReturn(String.class);
        doReturn(annotation).when(spyIntrospector)._findAnnotation(any(), eq(JsonDeserialize.class));

        MapperConfig<?> mockConfig = mock(MapperConfig.class);
        TypeFactory mockTf = mock(TypeFactory.class);
        when(mockConfig.getTypeFactory()).thenReturn(mockTf);
        // Throw error only on the content type refinement
        when(mockTf.constructSpecializedType(any(), any())).thenThrow(new IllegalArgumentException("Content Error"));

        JavaType baseType = typeFactory.constructCollectionType(java.util.List.class, String.class);
        when(annotated.getName()).thenReturn("failContentField");

        spyIntrospector.refineDeserializationType(mockConfig, annotated, baseType);
    }

    // Helper to bypass the fact that _findAnnotation is protected and we are in a different package 
    // if we weren't using a spy. But since we are using Mockito spy, it works.
    private JacksonAnnotationIntrospector spyIntrosceptor = spy(new JacksonAnnotationIntrospector());
}
